/**  Live header state of a chat. Never stored; coalesced to at most one per frame. */
export type SessionInfo = {
	worktree_setup?: WorktreeSetupAttempt | null,
	status: SessionStatus,
	/**  What is happening now: "Starting Hermes", "Stopping the turn; press Esc again to force stop". */
	detail: string | null,
	native_session_id: string | null,
	agent_name: string | null,
	agent_version: string | null,
	title: string | null,
	/**  Display labels of the current Model, Effort and Mode choices. */
	model: string | null,
	effort: string | null,
	mode: string | null,
	autonomy: Autonomy,
	/**  Some queued prompts are held ("Send queued" shows). */
	queue_held: boolean,
	/**
	 *  Increments when capabilities, options, slash commands or the autonomy state change: the UI
	 *  refetches `chat_lists`.
	 */
	revision: number,
	/**
	 *  Why the queued prompts are not going to the agent yet, while any are queued. `None` with
	 *  prompts queued means the next one is on its way.
	 */
	queue_wait: QueueWait | null,
	/**
	 *  The prompt on its way to the agent while its folder checkpoint saves: shown as sending in
	 *  the transcript, not in the queue. `None` once it went, or when a stop or a failed
	 *  checkpoint put it back in the queue, held.
	 */
	sending?: SendingPrompt | null,
	/**
	 *  The added account ([`agents::AgentAccount`]) the current or last start signed in with.
	 *  `None`: the agent's own sign-in, or no start yet.
	 */
	account_id?: string | null,
	/**
	 *  The agent said its usage limit is reached. Cleared when a turn completes or the agent
	 *  starts again, on another account or after the reset.
	 */
	usage_limit?: UsageLimit | null,
};

/**
 *  What the header's pickers and the slash menu show, fetched with `chat_lists` whenever
 *  [`SessionInfo::revision`] changes.
 */
export type SessionLists = {
	controls?: SessionControls,
	revision: number,
	/**  `None` until the agent has started once. */
	capabilities: Capabilities | null,
	options: ConfigOption[],
	commands: SlashCommand[],
	autonomy: AutonomyState,
	/**  What the running session loaded, where its agent reports it. */
	loaded?: SessionLoaded | null,
};

/**
 *  What a running session loaded, as its agent reports it once it starts: MCP servers with
 *  their state, skills, plugins and subagents. Each agent reports what it can: Claude all of it,
 *  Codex its MCP servers, Pi its skills.
 */
export type SessionLoaded = {
	mcp_servers: LoadedMcpServer[],
	skills: string[],
	plugins: LoadedPlugin[],
	agents: string[],
	/**  How many tools the agent offers, MCP tools included. */
	tools: number | null,
};

/**  Where a chat's agent is in its life. */
export type SessionStatus = 
/**  No process. */
"stopped" | "starting" | 
/**  The process is up and no turn runs. */
"ready" | 
/**  Exactly one turn is in flight. */
"running" | 
/**  The agent was asked to cancel; waiting for its reply. */
"cancelling" | "stopping" | 
/**  Could not start; no process. */
"failed" | 
/**  The agent needs its own sign-in; never a live process. */
"auth_required";

/**  What is installed and what is not. */
export type Setup = {
	/**  adb was found: phones on a cable can be used. */
	adb: boolean,
	/**  An emulator and an image for it were found: a device can be started. */
	emulator: boolean,
	/**  Whether the emulator can run fast here, once it is installed and was asked. */
	acceleration: AccelerationInfo | null,
	fetch: Fetch,
	ios: IosSetup,
};

export type SetupAction = { type: "visit"; step: SetupStep } | { type: "motion"; value: MotionPreference } | { type: "appearance"; value: AppearancePreference } | { type: "theme"; value: ThemePreference } | { type: "text_size"; value: TextSizePreference } | { type: "project"; project_id: string } | { type: "finish" } | { type: "restart" } | 
/**  Records tour stops as seen. Names already listed are kept once; the list only grows. */
{ type: "tour_seen"; stops: string[] } | 
/**
 *  Changing the agent clears the default model and thinking level, which belong to the
 *  previous agent.
 */
{ type: "default_agent"; agent_id: string | null } | 
/**  Changing the model clears the default thinking level, which was chosen for the old one. */
{ type: "default_model"; model: string | null } | { type: "default_effort"; effort: string | null } | { type: "default_autonomy"; value: Autonomy } | { type: "automatic_checkpoints"; enabled: boolean } | { type: "notifications"; enabled: boolean } | { type: "sounds"; enabled: boolean } | { type: "editor"; editor: ProjectEditor | null } | { type: "keep_awake"; enabled: boolean } | { type: "close_to_tray"; enabled: boolean } | 
/**  Turns on or off copying Git-ignored instruction files into new worktree chats. */
{ type: "copy_instructions_to_worktrees"; enabled: boolean } | 
/**  Turns on or off agents' edits to project memory. Off leaves it read-only for them. */
{ type: "agent_memory_writes"; enabled: boolean } | 
/**  Turns on or off showing a finished turn's work instead of folding it. */
{ type: "keep_steps_open"; enabled: boolean } | 
/**  Turns the Browser universal plugin on or off. */
{ type: "browser"; enabled: boolean } | 
/**  Turns on or off the browser's offer to save sign-ins. */
{ type: "browser_passwords"; enabled: boolean } | 
/**  Turns the Mobile universal plugin on or off. */
{ type: "mobile"; enabled: boolean } | 
/**  Turns on or off looking for a newer o7 by itself. */
{ type: "automatic_updates"; enabled: boolean } | 
/**  Turns the coordinated projects experiment on or off. */
{ type: "coordinated_projects"; enabled: boolean } | 
/**  Chooses the voice answers are read aloud in; `None` returns to the model's own. */
{ type: "speech_voice"; voice: string | null };

export type SetupCommand = {
	program: string,
	args: string[],
};

export type SetupFile = {
	path: string,
	bytes: number,
};

export type SetupPreferences = {
	revision: number,
	step: SetupStep,
	motion: MotionPreference,
	appearance: AppearancePreference,
	theme: ThemePreference,
	text_size: TextSizePreference,
	completed: boolean,
	first_project_id: string | null,
	/**
	 *  The tour's stops this profile has been shown or has declined, by name (owner,
	 *  22 November 2026: every feature with a UI joins the tour). A stop that is not listed is
	 *  new to this person, so an update that adds stops can offer a short flight of only those.
	 *  Empty for a profile that never met the tour; a file from before it reads as empty.
	 */
	tour_seen: string[],
	/**  Files written before these settings existed read their defaults ([`fill_defaults`]). */
	general: GeneralPreferences,
};

export type SetupSnapshot = {
	preferences: SetupPreferences,
	/**  Stable for this process, even when React remounts or the webview reloads. */
	cold_start: boolean,
	notice: string | null,
};

export type SetupStep = "welcome" | "agents" | "motion" | "project";

export type SlashCommand = {
	name: string,
	description: string,
	input_hint: string | null,
};

/**  One check a chat scenario made: its name, whether it held, and what was seen. */
export type SmokeCheck = {
	name: string,
	ok: boolean,
	/**  What the check saw, or why it failed (or did not run). */
	detail: string,
};

/**  What a smoke launch runs: its scenario, with the agent and folder the chat scenarios use. */
export type SmokePlan = {
	scenario: SmokeScenario,
	/**
	 *  The agent the chat scenarios create their chat with: the demo agent for `chat` and
	 *  `chat_reopen`, `O7_SMOKE_AGENT`'s for `agent`; `null` for `stream`.
	 */
	agent_id: string | null,
	/**  `O7_SMOKE_FOLDER`, which the folder picker answers; `null` for `stream`. */
	folder: string | null,
};

/**  What the UI's smoke run found. */
export type SmokeReport = {
	ok: boolean,
	/**
	 *  The scenario that ran; `null` only in a report made before any could (a smoke launch whose
	 *  switches were not valid).
	 */
	scenario: SmokeScenario | null,
	/**  The stream check's measurements; `null` for the chat scenarios. */
	stream: StreamMeasures | null,
	/**  Every check a chat scenario defines, in order; empty for the stream check. */
	checks: SmokeCheck[],
	errors: string[],
};

/**  Which scripted check a smoke launch runs. */
export type SmokeScenario = 
/**  A demo stream, a cancelled stream and a stress burst (`O7_SMOKE=1`). */
"stream" | 
/**
 *  The chat screens against the demo agent in a new data folder, ending with the quit flow
 *  while a turn runs (`O7_SMOKE=chat`).
 */
"chat" | 
/**
 *  The same data folder started again after `chat`: the stored history, the turn the quit
 *  interrupted, the prompt it held, and Resume (`O7_SMOKE=chat-reopen`).
 */
"chat_reopen" | 
/**
 *  One minimal chat with `O7_SMOKE_AGENT`'s agent (`O7_SMOKE=chat` with that set).
 *  For local runs only: a real agent spends the user's quota.
 */
"agent";

/**
 *  What one request to read aloud is doing. A request ends with exactly one of `Done`,
 *  `Stopped` or `Failed`.
 */
export type SpeechEvent = 
/**
 *  The voice model is loading, or the voice is being made ready: the first time, and the
 *  first time for each voice.
 */
{ state: "preparing" } | 
/**  Sound is coming out. */
{ state: "speaking" } | 
/**  All of it was said. */
{ state: "done" } | 
/**  It was stopped: by the person, by another request, or because its page went away. */
{ state: "stopped" } | { state: "failed"; message: string; reason: SpeechFailure };

/**  Why reading aloud failed, so the interface offers what can help. */
export type SpeechFailure = 
/**  The bundled voice model is missing or failed to load: reinstalling restores it. */
"model" | 
/**  There is no output device, or it stopped. */
"output" | 
/**  This processor lacks the instructions the speech engine needs. */
"unsupported" | "other";

export type SpeechStatus = {
	/**  The bundled model is here. */
	installed: boolean,
	/**  This processor can run the speech engine. */
	supported: boolean,
	name: string,
	/**  The voices that can be chosen, the model's own first. */
	voices: SpeechVoice[],
};

/**  A voice the person can choose. */
export type SpeechVoice = {
	/**  What a request names: `default`, or the catalogue's id for the voice. */
	id: string,
	name: string,
	/**  `en-us`, `en-gb`, or `characters` for the storybook voices. */
	locale: string,
	gender: string | null,
	/**  One line on how it sounds, from the catalogue. */
	description: string,
};

export type SteeringAck = {
	message_id: string,
	state: SteeringState,
	detail: string | null,
};

/**  Pending after a crash or a closed turn is unconfirmed, never proof of delivery. */
export type SteeringState = "pending" | "accepted" | "rejected" | "unconfirmed";

/**  Why a turn ended. */
export type StopReason = "end_turn" | "max_tokens" | "max_turn_requests" | "refusal" | 
/**  The agent confirmed a cancel. */
"cancelled" | 
/**  o7 ended the turn without the agent: a force stop, a crash, a quit. */
"interrupted" | "error" | 
/**  A reason o7 does not know (an agent's, or a newer build's). */
"other";

export type StorageState = { state: "ok" } | { state: "paused"; reason: PauseReason; since: number } | { state: "failed"; message: string };

/**  Whether the profile database is saving. */
export type StorageStatus = {
	state: StorageState,
	unsaved_bytes: number,
};

/**  What the stream check measured. */
export type StreamMeasures = {
	/**  Events applied across every stream of the run. */
	events_received: number,
	/**  Frames (`EventBatch`es) received across every stream of the run. */
	frames_received: number,
	/**  Sequence gaps the stream reducer detected. Any gap fails the run. */
	seq_gaps: number,
	/**  Characters of streamed answer text present in the rendered DOM. */
	rendered_chars: number,
	/**  Lowest frame rate over half-second windows of the stress burst. */
	fps_min: number | null,
	/**  Average frame rate over the stress burst. */
	fps_avg: number | null,
};

/**
 *  Settings for the stress view: `orbs` live orbs, a stream at `rate` tokens per second, the aura
 *  field on or off, for `seconds` seconds (0 keeps streaming until the window closes).
 */
export type StressConfig = {
	orbs: number,
	rate: number,
	aura: boolean,
	seconds: number,
};

/**  What the page shows and uses. */
export type SystemTerminalFont = {
	/**  The font family as CSS takes it, or `None` when only the size is known. */
	family: string | null,
	/**  The size in CSS pixels, or `None` when only the family is known. */
	size_px: number | null,
	/**  The same size in points, as the terminal's own settings say it. */
	size_points: number | null,
	/**  Where it came from, as Settings names it: "kitty", "GNOME" and the like. */
	source: string,
};

/**  What a task runs. */
export type TaskKind = 
/**  A subagent with its own conversation. */
"agent" | 
/**  A shell command. */
"command" | 
/**  A kind o7 does not know (an agent's newer kind, or a newer build's). */
"other";

/**  Where a task is in its life. */
export type TaskStatus = "running" | "completed" | "failed" | 
/**  Stopped or killed, or its turn or its agent's process ended before it reported an end. */
"stopped";

/**  One step of a task's work. */
export type TaskStep = {
	step_id: string,
	kind: TaskStepKind,
	/**  A tool's readable title ("Read main.rs"); empty for text. */
	title: string,
	tool_kind: ToolKind | null,
	/**  A tool's status. */
	status: ToolStatus | null,
	/**  A text step's markdown. */
	text: string | null,
	/**  The text was cut to fit the event budget; `blob` holds all of it. */
	truncated: Truncation | null,
};

/**  What a [`TaskStep`] shows. */
export type TaskStepKind = 
/**  A tool call the task made. */
"tool" | 
/**  Text the task's agent wrote. */
"text";

/**  One bounded pull. An empty nonterminal chunk means only that the read wait elapsed. */
export type TerminalChunk = {
	bytes: number[],
	done: boolean,
	exit_code: number | null,
	truncated: boolean,
};

/**
 *  How large the chat's text sets (owner, 4 November 2026: fit more text in, as Codex does).
 *  Compact is the default; Comfortable keeps the earlier, larger size. A file written before this
 *  setting existed, or naming a size this build lacks, reads as Compact ([`fill_defaults`]).
 */
export type TextSizePreference = "compact" | "comfortable";

/**
 *  The desktop's theme: Aura's own neutral palette, or one per supported agent (owner,
 *  3 November 2026). It belongs to the profile on this device, like appearance, and works in both
 *  appearances. Claude Code's is the default (owner, 4 November 2026): a profile that never chose
 *  one, or a file from a newer build that names a theme this build lacks, reads as it
 *  ([`fill_defaults`]). A saved choice, Aura included, is kept.
 */
export type ThemePreference = "aura" | "claude" | "codex" | "grok" | "pi" | "antigravity" | "cursor" | "opencode" | "oh_my_pi" | "hermes";

/**  Token accounting for a turn, when the agent reports it. */
export type TokenUsage = {
	input_tokens: number,
	output_tokens: number,
	/**  Tokens read from the prompt cache (ACP `cachedReadTokens`, Claude `cache_read_input_tokens`). */
	cache_read_tokens: number | null,
	/**
	 *  Tokens written to the prompt cache (ACP `cachedWriteTokens`, Claude
	 *  `cache_creation_input_tokens`).
	 */
	cache_write_tokens: number | null,
	/**  ACP `thoughtTokens`. */
	reasoning_tokens: number | null,
	scope: UsageScope,
};

/**  A tool invocation started by the agent. */
export type ToolCall = {
	tool_call_id: string,
	kind: ToolKind,
	title: string,
	status: ToolStatus,
	locations: ToolLocation[],
	/**  The tool's raw input as the agent sent it, for the expanded view. */
	raw_input: Value | null,
	/**  The tool's own name (ACP `ToolCall.name`). */
	tool_name: string | null,
	/**  ACP tool calls carry content from the start. */
	content: ToolContent[],
	/**  More than entry text was cut to fit the event budget; `blob` holds the original event's JSON. */
	truncated: Truncation | null,
};

/**  Rich content attached to a tool call or update. */
export type ToolContent = { type: "text"; text: string; truncated: Truncation | null } | { type: "diff"; path: string; 
/**  `None` when the file is new. */
old_text: string | null; new_text: string; truncated: Truncation | null } | { type: "terminal"; output: string; exit_code: number | null; truncated: Truncation | null };

/**  Fetching AXe. */
export type ToolFetch = { state: "missing" } | { state: "downloading"; received_mb: number | null; total_mb: number | null } | { state: "ready" } | { state: "failed"; message: string };

export type ToolKind = "read" | "edit" | "delete" | "move" | "search" | "execute" | "think" | "fetch" | "switch_mode" | "other";

export type ToolLocation = {
	path: string,
	line: number | null,
};

export type ToolStatus = "pending" | "in_progress" | "completed" | "failed";

/**
 *  Progress or result for a previously announced [`ToolCall`]. Mirrors ACP's update: `None` keeps a
 *  field; `content: Some(v)` replaces the content, and `Some([])` clears it.
 */
export type ToolUpdate = {
	tool_call_id: string,
	status: ToolStatus | null,
	title: string | null,
	kind: ToolKind | null,
	locations: ToolLocation[] | null,
	raw_input: Value | null,
	/**  ACP `ToolCallUpdateFields.name`. */
	tool_name: string | null,
	content: ToolContent[] | null,
	/**  As on [`ToolCall`]. */
	truncated: Truncation | null,
};

/**  A finger's phase, from the pane's pointer events. */
export type TouchPhase = "down" | "move" | "up";

/**  Inline content was cut; `blob` is the sha256 of the full content in the profile's attachments. */
export type Truncation = {
	total_bytes: number,
	blob: string | null,
};

/**  The agent one turn ran on. */
export type TurnAgent = {
	turn_id: string,
	agent_id: string,
	/**  The agent's display name ("Claude Code"). */
	agent_name: string,
};

/**  The answer to a [`UiRequest`], matching its [`UiPrompt`] (`Notify` takes none). */
export type UiAnswer = { type: "confirm"; yes: boolean } | { type: "select"; index: number } | { type: "input"; text: string } | { type: "questions"; answers: UiQuestionAnswer[] } | 
/**  A form submitted (`accept`) with its answered fields, or declined with none. */
{ type: "form"; accept: boolean; values: UiFieldValue[] };

/**  One field of a form. `id` is the schema property's name, which answers use. */
export type UiField = {
	id: string,
	label: string,
	description: string | null,
	required: boolean,
	kind: UiFieldKind,
};

export type UiFieldKind = { type: "text"; format: UiTextFormat | null; min_length: number | null; max_length: number | null; default: string | null } | { type: "number"; integer: boolean; minimum: number | null; maximum: number | null; default: number | null } | { type: "boolean"; default: boolean | null } | 
/**
 *  One choice or, with `multiple`, any number within the bounds. Answers name choices by
 *  position, so shortening a label for display never changes what is sent.
 */
{ type: "choice"; options: string[]; multiple: boolean; min_items: number | null; max_items: number | null; default: number[] };

/**  One answered field. A field left empty has no value at all. */
export type UiFieldValue = {
	id: string,
	value: UiValue,
};

export type UiPrompt = { type: "confirm"; message: string } | { type: "select"; message: string; options: string[] } | { type: "input"; message: string; placeholder: string | null } | { type: "questions"; message: string; questions: UiQuestion[] } | { type: "notify"; message: string } | 
/**
 *  An MCP server's form (MCP elicitation, form mode), answered with [`UiAnswer::Form`].
 *  `source` names the server.
 */
{ type: "form"; message: string; source: string | null; fields: UiField[] } | 
/**
 *  An MCP server asks the user to finish something in the browser (URL mode). Answered
 *  with [`UiAnswer::Confirm`]: yes once the page is opened, no to decline.
 */
{ type: "link"; message: string; source: string | null; 
/**  http or https only. */
url: string };

/**
 *  One question in a grouped prompt. The driver keeps the original native question and maps it by
 *  `id`, so display normalization never changes the key sent back to the agent.
 */
export type UiQuestion = {
	/**  Stable within the request and unique among its questions. */
	id: string,
	header: string,
	question: string,
	options: UiQuestionOption[],
	multi_select: boolean,
	allow_free_text: boolean,
};

/**
 *  One answer per question. A single-select question accepts one option or free text; a
 *  multi-select question accepts multiple options and optional free text. Nothing is preselected.
 */
export type UiQuestionAnswer = {
	question_id: string,
	/**  Distinct indices into the question's options, in their displayed order. */
	selected: number[],
	/**  Nonblank when present, and accepted only when the question allows free text. */
	text: string | null,
};

export type UiQuestionOption = {
	label: string,
	description: string,
};

/**
 *  An agent asks the UI for input that isn't a tool permission (Claude or Cursor questions,
 *  Pi extension UI, ACP elicitation, MCP forms). Never auto-answered.
 */
export type UiRequest = {
	request_id: string,
	prompt: UiPrompt,
};

/**  The string formats MCP forms can ask for. */
export type UiTextFormat = "email" | "uri" | "date" | "date_time";

export type UiValue = { type: "text"; text: string } | { type: "number"; number: number | null } | { type: "boolean"; value: boolean } | 
/**  Positions in the field's options, each at most once. */
{ type: "choices"; selected: number[] };

export type UpdateError = {
	message: string,
};

export type UpdatePhase = "disabled" | "idle" | "checking" | "available" | "downloading" | "ready" | "waiting_for_idle" | "installing" | "restart_required" | "failed";

export type UpdateStatus = {
	channel: string,
	phase: UpdatePhase,
	/**  The version running now. */
	current_version: string,
	/**  Whether o7 looks for a newer version by itself (Settings, General). */
	automatic: boolean,
	/**  The newer version, once a check has found one. */
	version: string | null,
	notes: string | null,
	downloaded_bytes: number,
	total_bytes: number | null,
	message: string | null,
};

/**  Context-window and spend information for the session. */
export type UsageInfo = {
	context_used: number | null,
	context_size: number | null,
	/**  The session's cumulative cost. */
	cost: Cost | null,
};

/**  An agent's own report that its account's usage limit is reached. */
export type UsageLimit = {
	/**  The agent's own words ("You've hit your 5-hour limit · resets 5:30pm (America/New_York)"). */
	message: string,
	resets_at: number | null,
};

/**  What a [`TokenUsage`] counts. */
export type UsageScope = 
/**  This turn alone. */
"turn" | 
/**  The whole native session so far ("this session" in the UI). */
"session";

export type Value = null | boolean | number | string | Value[] | { [key in string]: Value };

export type VendorAction = "install" | "update" | "remove" | "enable" | "disable" | "open";

export type VendorKind = "plugin" | "marketplace" | "package" | "native";

export type VendorProvider = "claude" | "codex" | "pi" | "open_code" | "hermes" | "cursor" | "grok" | "antigravity";

export type VendorRequest = {
	provider: VendorProvider,
	kind: VendorKind,
	action: VendorAction,
	target: string,
	/**  An optional Library item revision, checked against personal configuration only. */
	item_revision: string | null,
};

export type VendorReview = {
	token: string,
	request: VendorRequest,
	program: string,
	arguments: string[],
	working_directory: string,
	config_directory: string,
	revision: string,
	timeout_seconds: number,
	notices: string[],
};

/**  The installed version changed since the previous listing, so the listing was read again. */
export type VersionChange = {
	from: string,
	to: string,
};

/**  Evidence about this exact installed version, independent of whether its binary can start. */
export type VersionVerification = { state: "verified"; version: string; scope: string } | { state: "untested"; last_verified: string | null } | { state: "unknown" };

/**
 *  One packet of a device's video, sent to the page as raw bytes (the page reads an
 *  `ArrayBuffer`): a byte of kind, then the payload (`o7_devices::manager::Viewer`).
 */
export type VideoPacket = number[];

export type WorkspaceChat = {
	chat: ChatSummary,
	project_id: string,
	folder_id: string | null,
	pinned: boolean,
	archived: boolean,
	/**  The agent, model and thinking level this chat plans and builds with, where chosen. */
	roles?: ChatRoles,
};

export type WorkspaceFilter = {
	/**  Archived chats are excluded unless the caller explicitly asks to include them. */
	include_archived: boolean,
	/**  Filters chats only; projects remain available as move destinations. */
	project_id: string | null,
};

export type WorkspaceRemovalAction = "remove" | "restore";

export type WorkspaceRemovalPreview = {
	token: string,
	target: WorkspaceRemovalTarget,
	action: WorkspaceRemovalAction,
	name: string,
	chat_count: number,
	folders: string[],
	notices: string[],
};

export type WorkspaceRemovalTarget = { kind: "project"; id: string } | { kind: "folder"; id: string };

export type WorkspaceSnapshot = {
	projects: ProjectSummary[],
	chats: WorkspaceChat[],
};

export type WorktreeAction = { type: "merge"; message: string } | { type: "discard" };

export type WorktreeActionPreview = {
	token: string,
	worktree: ManagedWorktree,
	action: WorktreeAction,
	target: GitWorkspace | null,
	changes: string,
	conflicts: string[],
	warnings: string[],
	expires_at: number,
};

export type WorktreeActionResult = {
	worktree: ManagedWorktree,
	recovery: string,
	commit: string | null,
	error: string | null,
};

/**  A compact summary for a chip below the composer. */
export type WorktreeChatChip = {
	mode: ChatFolderMode,
	starting_branch: string | null,
	branch: string | null,
	label: string,
};

/**  One-step request for a new chat whose folder is a new app-owned worktree. */
export type WorktreeChatInput = {
	/**  The project folder the worktree is created from. It must be a repository root. */
	folder_id: string,
	agent_id: string,
	/**  A local branch to start from. `None` starts from the source folder's current branch. */
	start_branch: string | null,
	/**  The new branch. `None` picks a unique `aura/<slug>` name. An existing branch is never reused. */
	branch: string | null,
	/**  Optional chat title. It also names an automatic branch. */
	title: string | null,
	/**  Copy the source's uncommitted working files. Only allowed from the current commit. */
	bring_changes: boolean,
	/**  Run the source folder's saved worktree setup after creation. */
	run_setup: boolean,
};

export type WorktreeChatPlan = {
	token: string,
	source: GitWorkspace,
	starting_branch: string,
	starting_commit: string,
	branch: string,
	/**  True when the branch name was generated rather than typed. */
	branch_generated: boolean,
	path: string,
	bring_changes: boolean,
	/**  Local branches the starting branch can be chosen from, most recent first (bounded). */
	local_branches: string[],
	/**  The saved setup recipe that will run after creation, if any. */
	setup: WorktreeSetupInput | null,
	chip: WorktreeChatChip,
	warnings: string[],
	expires_at: number,
};

export type WorktreeChatPreview = { type: "worktree"; plan: WorktreeChatPlan } | 
/**  The folder is not a Git repository. The chat works directly in the folder instead. */
{ type: "not_git_repository"; folder: string; message: string; chip: WorktreeChatChip };

export type WorktreeChatResult = {
	chat: WorkspaceChat,
	worktree: ManagedWorktree,
	/**
	 *  Present when setup ran. A `command_token` starts the reviewed command in the owned
	 *  terminal (`worktree_setup_start`); the agent is then started explicitly.
	 */
	setup: WorktreeSetupResult | null,
	/**  True when the agent start was requested. */
	started: boolean,
	warnings: string[],
};

export type WorktreeDestination = "isolated" | "direct";

/**  The branch and source folder of a worktree o7 manages. */
export type WorktreeOrigin = {
	branch: string,
	source: string,
};

export type WorktreeRecovery = { type: "create" } | { type: "retire" } | { type: "restore" } | { type: "merge"; branch: string; before_ref: string; prepared_ref: string; before_commit: string; prepared_commit: string };

export type WorktreeRecoveryAction = "reconcile" | "restore";

export type WorktreeRecoveryPreview = {
	token: string,
	worktree: ManagedWorktree,
	action: WorktreeRecoveryAction,
	folder: GitWorkspace,
	target: GitWorkspace | null,
	destination: string,
	warnings: string[],
	expires_at: number,
};

export type WorktreeRecreatePreview = {
	token: string,
	worktree: ManagedWorktree,
	path: string,
	branch: string,
	commit: string,
	warnings: string[],
	expires_at: number,
};

export type WorktreeRelocationPreview = {
	token: string,
	worktree: ManagedWorktree,
	from: string,
	to: string,
	handoff: string,
	warnings: string[],
	expires_at: number,
};

/**
 *  A worktree chat's Run: the saved command, if any, and the first of the ten local ports the
 *  worktree's processes get (`O7_PORT`; Run also sets `PORT`).
 */
export type WorktreeRun = {
	command: SetupCommand | null,
	port: number,
	folder: string,
};

export type WorktreeSetup = {
	source: string,
	input: WorktreeSetupInput,
};

export type WorktreeSetupAttempt = {
	worktree_id: string,
	generation: number,
	state: WorktreeSetupState,
	detail: string | null,
};

export type WorktreeSetupInput = {
	files: string[],
	command: SetupCommand | null,
	/**
	 *  What Run starts in a worktree of this folder, with `O7_PORT` and `PORT` set to the
	 *  worktree's first port: a dev server, say. Recipes saved before Run have none.
	 */
	run?: SetupCommand | null,
};

export type WorktreeSetupPreview = {
	token: string,
	worktree_id: string,
	source: string,
	destination: string,
	files: SetupFile[],
	command: SetupCommand | null,
	warnings: string[],
	expires_at: number,
};

export type WorktreeSetupResult = {
	copied: string[],
	command_token: string | null,
	warning: string | null,
};

export type WorktreeSetupState = "awaiting" | "running" | "failed" | "interrupted" | "succeeded";

export type WorktreeState = "creating" | "ready" | "merging" | "retiring" | "restoring" | "recovery_required" | "missing" | "retired" | string;

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

